from __future__ import annotations

from datetime import datetime
import importlib.util
import io
import json
import os
from pathlib import Path
import re
import subprocess
import sys
import unittest


TOOL_DIR = Path(__file__).resolve().parents[1]
REPO_ROOT = TOOL_DIR.parents[1]
FIXTURES = Path(__file__).parent / "fixtures"
SCRIPT = TOOL_DIR / "codex_log_summary.py"
spec = importlib.util.spec_from_file_location("codex_log_summary", SCRIPT)
summary = importlib.util.module_from_spec(spec)
sys.modules[spec.name] = summary
# Keep generated bytecode inside the explicitly allowed tests directory.
previous_bytecode_setting = sys.dont_write_bytecode
sys.dont_write_bytecode = True
try:
    spec.loader.exec_module(summary)
finally:
    sys.dont_write_bytecode = previous_bytecode_setting


def item_event(item_type, phase="completed", **fields):
    return {"type": f"item.{phase}", "item": {"type": item_type, **fields}}


def without_timestamps(output):
    return re.sub(r"^\[\d{2}:\d{2}:\d{2}\] ", "", output, flags=re.MULTILINE)


class CommandSummaryTests(unittest.TestCase):
    def test_powershell_wrapper_and_escaped_quotes(self):
        command = r'''"C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe" -NoProfile -Command "python -c \"print('hi')\""'''
        self.assertEqual(summary.summarize_command(command), '''python -c "print('hi')"''')

    def test_powershell_variants(self):
        for command in (
            "powershell.exe -command 'Get-ChildItem'",
            "pwsh -NoProfile -c 'Get-ChildItem'",
            "powershell -Command Get-ChildItem",
        ):
            with self.subTest(command=command):
                self.assertEqual(summary.summarize_command(command), "Get-ChildItem")

    def test_bash_wrappers(self):
        for command in (
            "bash -lc 'python hello.py'",
            '/usr/bin/bash --login -c "python hello.py"',
            "bash -cl 'python hello.py'",
        ):
            with self.subTest(command=command):
                self.assertEqual(summary.summarize_command(command), "python hello.py")

    def test_bash_embedded_single_quote(self):
        self.assertEqual(
            summary.summarize_command("bash -lc 'printf '\\''hello'\\'''"),
            "printf 'hello'",
        )

    def test_multiline_never_discloses_subsequent_lines(self):
        commands = (
            "bash -lc 'cat > example.py <<EOF\nSECRET_CODE\nEOF'",
            'powershell.exe -Command "Set-Content example.py @\'\r\nSECRET_CODE\r\n\'@"',
            "unknown-shell arg\nSECRET_CODE\nMORE_SECRET",
        )
        expected = (
            "cat > example.py <<EOF (+2行)",
            "Set-Content example.py @' (+2行)",
            "unknown-shell arg (+2行)",
        )
        for command, result in zip(commands, expected):
            with self.subTest(command=command):
                self.assertEqual(summary.summarize_command(command), result)

    def test_long_first_line_and_line_count(self):
        self.assertEqual(
            summary.summarize_command("bash -lc '" + "あ" * 121 + "\nSECRET'"),
            "あ" * 119 + "… (+1行)",
        )
        self.assertEqual(summary.summarize_command("a" * 120), "a" * 120)

    def test_unexpected_wrapper_or_missing_command_does_not_crash(self):
        cases = (
            ("bash -lc 'unterminated\nSECRET", "'unterminated (+1行)"),
            ('powershell.exe -File script.ps1', 'powershell.exe -File script.ps1'),
            ('"unterminated shell\nSECRET', '"unterminated shell (+1行)'),
            ("bash", "bash"),
            (None, "?"),
            ({"command": "unexpected"}, "?"),
        )
        for command, expected in cases:
            with self.subTest(command=command):
                self.assertEqual(summary.summarize_command(command), expected)

    def test_trailing_newline_does_not_add_a_line(self):
        self.assertEqual(summary.summarize_command("echo hi\n"), "echo hi")

    def test_shell_switch_on_later_line_does_not_expose_that_line(self):
        self.assertEqual(
            summary.summarize_command("powershell.exe -File script.ps1\n-Command SECRET_CODE"),
            "powershell.exe -File script.ps1 (+1行)",
        )
        self.assertEqual(
            summary.summarize_command("bash --login\n-lc SECRET_CODE"),
            "bash --login (+1行)",
        )

    def test_blank_first_body_line_does_not_expose_second_line(self):
        self.assertEqual(summary.summarize_command("bash -lc '\nSECRET_CODE'"), "? (+1行)")
        self.assertEqual(summary.summarize_command("powershell.exe -Command\nSECRET_CODE"), "? (+1行)")


class EventFormattingTests(unittest.TestCase):
    def setUp(self):
        self.state = summary.SummaryState(root="/work/project")

    def test_success_suppresses_aggregated_output(self):
        event = item_event("command_execution", command="echo hi", exit_code=0,
                           status="completed", aggregated_output="SECRET\n")
        self.assertEqual(summary.format_event(event, self.state), ["$ echo hi  → OK"])

    def test_failure_shows_only_last_five_lines_limited_to_200_characters(self):
        event = item_event("command_execution", command="python broken.py", exit_code=2,
                           status="failed", aggregated_output="hidden1\nhidden2\n3\n4\n5\n6\n" + "失" * 201 + "\n")
        self.assertEqual(summary.format_event(event, self.state), [
            "$ python broken.py  → 失敗 (exit 2)",
            "    | 3", "    | 4", "    | 5", "    | 6", "    | " + "失" * 199 + "…",
        ])

    def test_nonzero_exit_is_failure_even_with_completed_status(self):
        self.assertEqual(summary.format_event(
            item_event("command_execution", command="false", exit_code=1, status="completed"),
            self.state,
        ), ["$ false  → 失敗 (exit 1)"])

    def test_failed_status_without_exit_code(self):
        self.assertEqual(summary.format_event(
            item_event("command_execution", command="false", status="failed"), self.state,
        ), ["$ false  → 失敗 (exit ?)"])

    def test_command_and_mcp_only_print_at_item_completion(self):
        for item_type in ("command_execution", "mcp_tool_call"):
            for phase in ("started", "updated"):
                with self.subTest(item_type=item_type, phase=phase):
                    self.assertEqual(summary.format_event(
                        item_event(item_type, phase, status="failed"), self.state,
                    ), [])
            for status in ("in_progress", "declined"):
                with self.subTest(item_type=item_type, status=status):
                    self.assertEqual(summary.format_event(
                        item_event(item_type, status=status), self.state,
                    ), [])

    def test_completed_only_items_and_reasoning(self):
        for item_type in ("agent_message", "file_change", "web_search"):
            for phase in ("started", "updated"):
                with self.subTest(item_type=item_type, phase=phase):
                    self.assertEqual(summary.format_event(item_event(item_type, phase), self.state), [])
        for phase in ("started", "updated", "completed"):
            self.assertEqual(summary.format_event(item_event("reasoning", phase, text="SECRET"), self.state), [])

    def test_agent_message_line_joining_and_truncation(self):
        self.assertEqual(summary.format_event(
            item_event("agent_message", text="一行目\r\n\n 二行目 "), self.state,
        ), ["💬 一行目 二行目"])
        self.assertEqual(summary.format_event(
            item_event("agent_message", text="あ" * 301), self.state,
        ), ["💬 " + "あ" * 299 + "…"])

    def test_file_changes_relative_paths_and_six_entry_limit(self):
        changes = [
            {"kind": kind, "path": f"/work/project/src/{index}.py"}
            for index, kind in enumerate(("add", "update", "delete", "add", "update", "delete", "add", "add"))
        ]
        self.assertEqual(summary.format_event(
            item_event("file_change", status="completed", changes=changes), self.state,
        ), ["✎ 変更: add src/0.py, update src/1.py, delete src/2.py, add src/3.py, update src/4.py, delete src/5.py ほか 2 件"])

    def test_windows_paths_relative_and_different_drive(self):
        self.assertEqual(summary.relative_path(r"C:\work\project\src\a.py", r"C:\work\project"), "src/a.py")
        self.assertEqual(summary.relative_path(r"c:\WORK\project\a.py", r"C:\work\project"), "a.py")
        self.assertEqual(summary.relative_path(r"D:\other\a.py", r"C:\work\project"), "D:/other/a.py")
        self.assertEqual(summary.relative_path("/work/other/a.py", "/work/project"), "../other/a.py")

    def test_todo_displays_only_content_changes(self):
        entries = [{"text": "実装", "completed": False}, {"text": "テスト", "completed": False}]
        self.assertEqual(summary.format_event(item_event("todo_list", "started", items=entries), self.state), ["☑ TODO 0/2: 実装"])
        self.assertEqual(summary.format_event(item_event("todo_list", "updated", items=entries, id="different"), self.state), [])
        entries[0]["completed"] = True
        self.assertEqual(summary.format_event(item_event("todo_list", "updated", items=entries), self.state), ["☑ TODO 1/2: テスト"])
        entries[1]["text"] = "追加テスト"
        self.assertEqual(summary.format_event(item_event("todo_list", items=entries), self.state), ["☑ TODO 1/2: 追加テスト"])
        entries[1]["completed"] = True
        self.assertEqual(summary.format_event(item_event("todo_list", items=entries), self.state), ["☑ TODO 2/2: (未完了なし)"])
        self.assertEqual(summary.format_event(item_event("todo_list", items=[]), self.state), ["☑ TODO 0/0: (未完了なし)"])

    def test_missing_fields_use_defaults(self):
        cases = [
            ({"type": "thread.started"}, ["▶ 開始 thread=?"]),
            ({"type": "turn.completed"}, ["■ 完了 tokens: in=0 (cached 0) out=0"]),
            ({"type": "turn.failed"}, ["✖ 失敗: 不明なエラー"]),
            ({"type": "error"}, ["⚠ 不明なエラー"]),
            (item_event("agent_message"), ["💬 "]),
            (item_event("command_execution"), ["$ ?  → OK"]),
            (item_event("file_change", changes=[{}]), ["✎ 変更: ? ?"]),
            (item_event("web_search"), ["🔎 検索: "]),
            (item_event("mcp_tool_call"), ["🔧 ?.? → OK"]),
            (item_event("error"), ["⚠ 不明なエラー"]),
        ]
        for event, expected in cases:
            with self.subTest(event=event):
                self.assertEqual(summary.format_event(event, self.state), expected)

    def test_unknown_types_and_wrong_field_shapes_do_not_crash(self):
        cases = [None, [], 1, "text", {}, {"type": []}, {"type": "unknown"},
                 {"type": "item.completed", "item": []}, item_event("unknown"),
                 {"type": "turn.completed", "usage": []}, {"type": "turn.failed", "error": []},
                 item_event("command_execution", command=[], status=[], exit_code=[], aggregated_output=[]),
                 item_event("file_change", changes=[None, [], {"kind": [], "path": []}]),
                 item_event("todo_list", items=[None, [], {"text": [], "completed": []}]),
                 item_event("mcp_tool_call", server=[], tool=[], status=[])]
        for event in cases:
            with self.subTest(event=event):
                result = summary.format_event(event, self.state)
                self.assertIsInstance(result, list)
        for event in cases[:9]:
            self.assertEqual(summary.format_event(event, self.state), [])

    def test_every_item_type_is_in_synthetic_fixture(self):
        events = [json.loads(line) for line in (FIXTURES / "all-items.jsonl").read_text(encoding="utf-8").splitlines()]
        types = {event["item"]["type"] for event in events if "item" in event}
        self.assertTrue({"agent_message", "reasoning", "command_execution", "file_change", "todo_list", "web_search", "mcp_tool_call", "error"} <= types)


class StreamAndCliTests(unittest.TestCase):
    def test_real_sample_output_matches_snapshot(self):
        source = REPO_ROOT / ".codex-runs/004-codex-log-summary/sample-real.jsonl"
        self._check_fixture(source, FIXTURES / "sample-real.expected.txt")

    def test_synthetic_fixture_matches_snapshot(self):
        self._check_fixture(FIXTURES / "all-items.jsonl", FIXTURES / "all-items.expected.txt")

    def test_readme_example_is_actual_synthetic_output(self):
        output = io.StringIO()
        with (FIXTURES / "all-items.jsonl").open(encoding="utf-8") as source:
            summary.process_stream(source, output, now=lambda: datetime(2026, 10, 4, 12, 34, 56))
        readme = (TOOL_DIR / "README.md").read_text(encoding="utf-8")
        example = readme.split("```text\n", 1)[1].split("```", 1)[0]
        self.assertEqual(example, output.getvalue())

    def _check_fixture(self, source, expected):
        output = io.StringIO()
        with source.open(encoding="utf-8") as input_stream:
            summary.process_stream(input_stream, output, now=lambda: datetime(2026, 10, 4, 12, 34, 56))
        self.assertEqual(without_timestamps(output.getvalue()), expected.read_text(encoding="utf-8"))
        for line in output.getvalue().splitlines():
            self.assertTrue(line.startswith("[12:34:56] "))

    def test_invalid_json_is_truncated_and_partial_last_line_is_preserved(self):
        output = io.StringIO()
        summary.process_stream(io.StringIO("x" * 201 + '\n{"type":"thread.started"}\n{"type":'), output)
        self.assertEqual(without_timestamps(output.getvalue()), "· " + "x" * 199 + "…\n▶ 開始 thread=?\n· {\"type\":\n")

    def test_deeply_nested_invalid_json_does_not_stop_stream(self):
        output = io.StringIO()
        summary.process_stream(io.StringIO("[" * 2000 + "]" * 2000 + '\n{"type":"error","message":"続行"}\n'), output)
        self.assertTrue(without_timestamps(output.getvalue()).endswith("⚠ 続行\n"))

    def test_flush_happens_before_reading_next_event_including_suppressed_events(self):
        class ObservedOutput(io.StringIO):
            def __init__(self):
                super().__init__()
                self.snapshots = []

            def flush(self):
                self.snapshots.append(self.getvalue())

        output = ObservedOutput()
        events = [
            '{"type":"thread.started","thread_id":"live"}\n',
            '{"type":"turn.started"}\n',
            json.dumps(item_event("command_execution", command="false", status="failed", exit_code=1, aggregated_output="line1\nline2")) + "\n",
            '{"type":',
        ]

        def input_events():
            for index, event in enumerate(events):
                self.assertEqual(len(output.snapshots), index)
                yield event
            self.assertEqual(len(output.snapshots), len(events))

        summary.process_stream(input_events(), output)
        self.assertEqual(len(output.snapshots), 4)
        self.assertIn("▶ 開始 thread=live", output.snapshots[0])
        self.assertEqual(output.snapshots[0], output.snapshots[1])
        self.assertIn("    | line2", output.snapshots[2])

    def test_utf8_reconfiguration_and_replacement_in_text_streams(self):
        source = io.TextIOWrapper(io.BytesIO(b'{"type":"error","message":"\xff"}\n'), encoding="cp932")
        sink_bytes = io.BytesIO()
        sink = io.TextIOWrapper(sink_bytes, encoding="cp932")
        summary.process_stream(source, sink, now=lambda: datetime(2026, 10, 4, 1, 2, 3))
        self.assertEqual(sink_bytes.getvalue().decode("utf-8"), "[01:02:03] ⚠ �\n")

    def _run_cli(self, data, *args):
        environment = os.environ.copy()
        environment["PYTHONIOENCODING"] = "cp932:strict"
        return subprocess.run([sys.executable, str(SCRIPT), *args], input=data, capture_output=True,
                              cwd=REPO_ROOT, env=environment, check=False, timeout=10)

    def test_cli_utf8_invalid_bytes_and_truncated_input_exit_zero(self):
        data = '{"type":"thread.started","thread_id":"日本語"}\n'.encode("utf-8")
        data += b'{"type":"error","message":"\xff"}\n{"type":'
        result = self._run_cli(data)
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(result.stderr, b"")
        self.assertEqual(without_timestamps(result.stdout.decode("utf-8")), "▶ 開始 thread=日本語\n⚠ �\n· {\"type\":\n")

    def test_cli_replaces_unencodable_json_surrogate(self):
        result = self._run_cli(b'{"type":"error","message":"\\ud800"}\n')
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(without_timestamps(result.stdout.decode("utf-8")), "⚠ ?\n")

    def test_cli_root_argument_and_default_cwd(self):
        path = TOOL_DIR / "README.md"
        data = (json.dumps(item_event("file_change", changes=[{"kind": "add", "path": str(path)}])) + "\n").encode("utf-8")
        result = self._run_cli(data)
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(without_timestamps(result.stdout.decode("utf-8")), "✎ 変更: add tools/codex-log-summary/README.md\n")
        result = self._run_cli(data, "--root", str(TOOL_DIR))
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(without_timestamps(result.stdout.decode("utf-8")), "✎ 変更: add README.md\n")

    def test_empty_input_exits_zero(self):
        result = self._run_cli(b"")
        self.assertEqual((result.returncode, result.stdout, result.stderr), (0, b"", b""))


if __name__ == "__main__":
    unittest.main()
